(37509, 'Genesis 15:14', 'Genesis', 15, 14, 'خو زه به هغه قوم ته چې دوی یې غلامي کوي، سزا ورکړم او له هغې وروسته به دوی د ډېرې شتمنۍ سره ووځي.', 'خو زه به هغه قوم ته چې دوی یې غلامی کوی، سزا ورکرم او له هغې وروسته به دوی د دېرې شتمنی سره ووجی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_15_14.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
(37510, 'Genesis 15:15', 'Genesis', 15, 15, 'ته به په پاخه عمر کې په ارامۍ سره مړ شې او ښخ به شې.', 'ته به په پاخه عمر کې په ارامی سره مر شې او شخ به شې.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_15_15.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
(37511, 'Genesis 15:16', 'Genesis', 15, 16, 'ستا اولاده به له څلورم نسل څخه وروسته بېرته دلته راشي، ځکه زه به تر هغې پورې اموریان ونه شړم، ترڅو پورې چې هغوی دومره بدکاره شي چې باید سزا ومومي.»', 'ستا اولاده به له چلورم نسل چخه وروسته بېرته دلته راشی، جکه زه به تر هغې پورې اموریان ونه شرم، ترچو پورې چې هغوی دومره بدکاره شی چې باید سزا ومومی.»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_15_16.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
(37512, 'Genesis 15:17', 'Genesis', 15, 17, 'کله چې لمر پرېوت او تیاره شوه، د لوګي څخه ډک یو تنور او بلېدونکی څراغ راښکاره شول او د دې ټوټو له منځ څخه تېر شول.', 'کله چې لمر پرېوت او تیاره شوه، د لوګی چخه دک یو تنور او بلېدونکی چراغ راشکاره شول او د دې توتو له منج چخه تېر شول.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_15_17.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
(37513, 'Genesis 15:18', 'Genesis', 15, 18, 'په هماغه ورځ څښتن د ابرام سره لوظ وکړ او ویې ویل: «زه ستا اولادې ته دا ټوله خاوره د مصر د سیند څخه نیولې د فرات تر لوی سیند پورې ورکوم', 'په هماغه ورج چشتن د ابرام سره لوظ وکر او ویې ویل: «زه ستا اولادې ته دا توله خاوره د مصر د سیند چخه نیولې د فرات تر لوی سیند پورې ورکوم', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_15_18.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237839, 1761237839),
(37514, 'Genesis 15:19', 'Genesis', 15, 19, 'یعنې د قینیانو، قنزیانو، قدمونیانو،', 'یعنې د قینیانو، قنزیانو، قدمونیانو،', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_15_19.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237839, 1761237839),
(37515, 'Genesis 15:20', 'Genesis', 15, 20, 'حیتیانو، فرزیانو، رفاییانو،', 'حیتیانو، فرزیانو، رفاییانو،', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_15_20.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
(37516, 'Genesis 15:21', 'Genesis', 15, 21, 'اموریانو، کنعانیانو، جرجاشیانو او یبوسیانو خاوره.»', 'اموریانو، کنعانیانو، جرجاشیانو او یبوسیانو خاوره.»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_15_21.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
(37517, 'Job 10:1', 'Job', 10, 1, 'زۀ د خپل ژوند نه نفرت کوم، زۀ به ډېر شکايتونه کوم، زۀ به په مايوسۍ کښې خبرې کوم.', 'زۀ د خپل ژوند نه نفرت کوم، زۀ به دېر شکایتونه کوم، زۀ به په مایوسی کشې خبرې کوم.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_10_1.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
(37518, 'Job 10:2', 'Job', 10, 2, 'زۀ به خُدائ پاک ته ووايم چې ما مۀ رد کوه، او تۀ چې په ما کوم اِلزام لګوې نو د هغې نه ما خبر کړه.', 'زۀ به خدای پاک ته ووایم چې ما مۀ رد کوه، او تۀ چې په ما کوم الزام لګوې نو د هغې نه ما خبر کره.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_10_2.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
(37519, 'Job 10:3', 'Job', 10, 3, 'دا تا ته ښۀ ښکارى، چې ما په عذاب کړې، چې ما يعنې د خپلو لاسونو کار رد کړې او د بدکارو خلقو منصوبو ته ښۀ ووائې؟', 'دا تا ته شۀ شکاری، چې ما په عذاب کرې، چې ما یعنې د خپلو لاسونو کار رد کرې او د بدکارو خلقو منصوبو ته شۀ ووایې؟', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_10_3.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
(37520, 'Job 10:4', 'Job', 10, 4, 'ولې ستا نظر د انسانانو په شان دے؟ تۀ د انسان په شان کتل کوې څۀ؟', 'ولې ستا نظر د انسانانو په شان دے؟ تۀ د انسان په شان کتل کوې چۀ؟', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_10_4.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
(37521, 'Job 10:5', 'Job', 10, 5, 'ستا عُمر زمونږ په شان لنډ دے څۀ؟ يا ستا کالونه د انسانانو د کالونو په شان دى څۀ؟', 'ستا عمر زمونز په شان لند دے چۀ؟ یا ستا کالونه د انسانانو د کالونو په شان دی چۀ؟', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_10_5.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237839, 1761237839),
(37522, 'Job 10:6', 'Job', 10, 6, 'چې تۀ زما غلطى معلوموې او زما ګناه لټوې،', 'چې تۀ زما غلطی معلوموې او زما ګناه لتوې،', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_10_6.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
(37523, 'Job 10:7', 'Job', 10, 7, 'اګر چې تا ته پته ده چې زۀ بې‌ګناه يم، او ستا د لاسونو نه مې هيڅ څوک نۀ شى بچ کولے.', 'اګر چې تا ته پته ده چې زۀ بې‌ګناه یم، او ستا د لاسونو نه مې هیچ چوک نۀ شی بچ کولے.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_10_7.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237839, 1761237839),
(37524, 'Job 10:8', 'Job', 10, 8, 'ستا لاسونو ما له صورت راکړو او جوړ يې کړم، او اوس مې بېخى تباه کوې.', 'ستا لاسونو ما له صورت راکرو او جور یې کرم، او اوس مې بېخی تباه کوې.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_10_8.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
(37525, 'Job 10:9', 'Job', 10, 9, 'هغه راپه ياد کړه چې تا زۀ د خټو نه جوړ کړم، او اوس به تۀ ما بيا خاورې کوې؟', 'هغه راپه یاد کره چې تا زۀ د ختو نه جور کرم، او اوس به تۀ ما بیا خاورې کوې؟', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_10_9.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
(37526, 'Job 10:10', 'Job', 10, 10, 'تا زۀ د مور په خېټه کړم او زما وجود دې جوړ کړو.', 'تا زۀ د مور په خېته کرم او زما وجود دې جور کرو.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_10_10.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237839, 1761237839),
(37527, 'Job 10:11', 'Job', 10, 11, 'تا زۀ د غوښې او څرمنې نه جوړ کړم، او د هډُوکو او پټو په ذريعه دې يو ځائ وتړلم.', 'تا زۀ د غوشې او چرمنې نه جور کرم، او د هدوکو او پتو په ذریعه دې یو جای وترلم.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_10_11.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
(37528, 'Job 10:12', 'Job', 10, 12, 'تا ما له ژوند او نۀ ختمېدونکې مينه راکړې ده، او تا زما د ژوند ښۀ حِفاظت کړے دے.', 'تا ما له ژوند او نۀ ختمېدونکې مینه راکرې ده، او تا زما د ژوند شۀ حفاظت کرے دے.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_10_12.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
(37529, 'Job 10:13', 'Job', 10, 13, 'خو اوس ما ته پته ولګېده چې تا د ډېر وخت نه ما ته د نقصان دپاره پټه منصوبه جوړه کړې وه.', 'خو اوس ما ته پته ولګېده چې تا د دېر وخت نه ما ته د نقصان دپاره پته منصوبه جوره کرې وه.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_10_13.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
(37530, 'Job 10:14', 'Job', 10, 14, 'کۀ زۀ ګناه وکړم نو تۀ ما وينې، او زما ګناه تۀ نۀ معاف کوې.', 'کۀ زۀ ګناه وکرم نو تۀ ما وینې، او زما ګناه تۀ نۀ معاف کوې.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_10_14.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237839, 1761237839),
(37531, 'Job 10:15', 'Job', 10, 15, 'کۀ زۀ بدکاره يم، نو ما غمژن کړه. او کۀ زۀ صادق يم، نو خپل سر نۀ شم اوچتولے، ځکه چې زۀ د شرم سره مخ شوے يم او په غمونو کښې ډوب يم.', 'کۀ زۀ بدکاره یم، نو ما غمژن کره. او کۀ زۀ صادق یم، نو خپل سر نۀ شم اوچتولے، جکه چې زۀ د شرم سره مخ شوے یم او په غمونو کشې دوب یم.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_10_15.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
(37532, 'Job 10:16', 'Job', 10, 16, 'او کۀ زۀ خپل سر اوچتوم، نو تۀ د ازمرى په شان زما ښکار کوې، او خپل لوئ طاقت زما خِلاف استعمالوې.', 'او کۀ زۀ خپل سر اوچتوم، نو تۀ د ازمری په شان زما شکار کوې، او خپل لوی طاقت زما خلاف استعمالوې.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_10_16.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237839, 1761237839),
(37533, 'Job 10:17', 'Job', 10, 17, 'تۀ خپل ګواهان زما خِلاف بيا راتازه کړې، او خپله غصه زما خِلاف زياتوې، تۀ زما خِلاف تازه دم فوجيان رالېږې.', 'تۀ خپل ګواهان زما خلاف بیا راتازه کرې، او خپله غصه زما خلاف زیاتوې، تۀ زما خلاف تازه دم فوجیان رالېزې.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_10_17.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
(37534, 'Job 10:18', 'Job', 10, 18, 'تا زۀ د مور د خېټې نه ولې راوويستلم؟ کاش چې زۀ د خلقو د سترګو د ليدو نه مخکښې مړ شوے وے.', 'تا زۀ د مور د خېتې نه ولې راوویستلم؟ کاش چې زۀ د خلقو د سترګو د لیدو نه مخکشې مر شوے وے.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_10_18.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
(37535, 'Job 10:19', 'Job', 10, 19, 'ښۀ به دا وے چې د سره پېدا شوے نۀ وے او د مور د خېټې نه سيدها قبر ته تلے وے.', 'شۀ به دا وے چې د سره پېدا شوے نۀ وے او د مور د خېتې نه سیدها قبر ته تلے وے.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_10_19.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237839, 1761237839),
(37536, 'Job 10:20', 'Job', 10, 20, 'زما ژوند لنډ نۀ دے څۀ؟ ما پرېږده نو چې داسې يو ساعت په آرام شم،', 'زما ژوند لند نۀ دے چۀ؟ ما پرېزده نو چې داسې یو ساعت په ارام شم،', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_10_20.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237839, 1761237839),
(37537, 'Job 10:21', 'Job', 10, 21, 'خو چې زۀ لاړ شم او بيا هيڅکله راواپس نۀ شم، چې تور او د تکې تورې تيارې مُلک ته لاړ شم،', 'خو چې زۀ لار شم او بیا هیچکله راواپس نۀ شم، چې تور او د تکې تورې تیارې ملک ته لار شم،', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_10_21.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
(37538, 'Job 10:22', 'Job', 10, 22, 'د نيمې شپې په شان تيارۀ، د لانجو مُلک ته، چرته چې رڼا هم د تيارې په شان وى.“', 'د نیمې شپې په شان تیارۀ، د لانجو ملک ته، چرته چې رنا هم د تیارې په شان وی.“', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_10_22.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
(37539, 'Psalms 88:1', 'Psalms', 88, 1, 'ای څښتن خدایه خلاصوونکیه زما ټوله ورځ تاته زاري کړم د شپې ستا حضور ته ژاړم', 'ای چشتن خدایه خلاصوونکیه زما توله ورج تاته زاری کرم د شپې ستا حضور ته ژارم', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_88_1.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
